const express = require('express');
const { authGuard } = require('../auth');
const { UserPreference } = require('../models/preference');

const app = express();

app.get('/api/preferences/notifications', authGuard, async (req, res) => {
  // Always enforce verified user identity from authenticated token
  const userId = req.user.id;

  const prefs = await UserPreference.findOne({ where: { userId } });
  if (!prefs) return res.status(404).json({ error: 'Preferences not found' });

  res.json({
    userId,
    emailAlerts: prefs.emailAlerts,
    phoneAlerts: prefs.phoneNumber,
    slackWebhook: prefs.slackWebhookUrl
  });
});

module.exports = app;
